<?php
require dirname(__DIR__).'/vendor/autoload.php';
use app\services\CatalogLegacyPreview as L;use app\services\CatalogProperties as P;use app\services\CatalogMigrationPlan as M;use app\services\CatalogSize as Z;
function remainingCheck($ok,$message){if(!$ok)throw new RuntimeException($message);}
function remainingPreview($category,$attrs,$name='Test'){$a=[];foreach($attrs as $id=>$v)$a[]=['attribute_id'=>$id,'attribute_text'=>$v];return L::forProduct(['id'=>1,'sku'=>'TEST','name'=>$name,'category_id'=>$category],$a);}
$ring=remainingPreview(41,[59=>'5.00S-12',75=>'Коническое посадочное']);remainingCheck($ring['proposed']['type']==='rim_ring'&&$ring['proposed']['values']['rim_ring_type']['value']===['conical']&&!$ring['unmapped'],'Rim ring has its own profile and dictionary');remainingCheck(P::applicability('rim_width_in','rim_ring')==='not_applicable'&&P::applicability('rim_ring_type','rim_ring')==='required','Ring not treated as full rim');
$rim=remainingPreview(26,[56=>'32',55=>'200']);remainingCheck($rim['proposed']['values']['bolt_hole_diameter_mm']['value']==='32'&&$rim['proposed']['values']['pcd_mm']['value']==='200','Hole diameter is not PCD');
$tyre=remainingPreview(18,[4=>'5.00-8',16=>'Шина цельнолитая',21=>'470']);remainingCheck($tyre['proposed']['type']==='tyre_solid'&&$tyre['proposed']['values']['tire_type']['value']===['solid']&&!isset($tyre['proposed']['values']['sealing'])&&!$tyre['unmapped'],'Explicit misplaced type is routed without inventing sealing');remainingCheck($tyre['proposed']['values']['overall_diameter_mm']['value']==='470'&&!isset($tyre['proposed']['values']['filter_outer_diameter_mm']),'Tire diameter routed by profile');remainingCheck(str_contains($tyre['proposed']['values']['tire_type']['source_ref'],'Шина цельнолитая'),'Original type preserved');
$filter=remainingPreview(11,[14=>'200']);remainingCheck($filter['proposed']['values']['filter_outer_diameter_mm']['value']==='200'&&!isset($filter['proposed']['values']['overall_diameter_mm'])&&!$filter['unmapped'],'Filter diameter routed by profile');
$conflict=remainingPreview(11,[14=>'200',21=>'210']);remainingCheck(M::decide($conflict,false)['decision']==='hold','Distinct diameter sources cannot overwrite one another');
$seal=remainingPreview(33,[4=>'15.5-25, 17.5-25',68=>'7']);remainingCheck(count($seal['proposed']['sizes'])===2&&$seal['proposed']['sizes'][0]['role']==='compatible'&&!$seal['unmapped'],'Seal compatible dimensions are not its section diameter');
$unknown=remainingPreview(18,[4=>'6.50-10',16=>'TL']);remainingCheck($unknown['proposed']['type']==='unclassified'&&M::decide($unknown,false)['decision']==='hold','TL alone never proves tire type');
$conflict=remainingPreview(18,[61=>'пневматические',16=>'Шина цельнолитая']);remainingCheck(M::decide($conflict,false)['decision']==='hold','Explicit types disagree');
$conflict=remainingPreview(18,[61=>'пневматические',16=>'Шина цельнолитая'],'Колесо в сборе с диском');remainingCheck(M::decide($conflict,false)['decision']==='hold','Explicit types also checked for wheel assembly');
$surface=remainingPreview(18,[61=>'пневматические',62=>'грунт, песок, глина']);remainingCheck($surface['proposed']['values']['surface']['value']===['soil','sand','clay'],'Clay remains separate');
$excavator=remainingPreview(31,[15=>'Экскаватор']);remainingCheck($excavator['proposed']['values']['equipment_application']['value']===['excavator_generic'],'Generic excavator never narrowed to wheeled');
remainingCheck(Z::normalize('28*9-15')==='28x9-15','Explicit tire-size separator normalized');$rejected=false;try{Z::normalize('2*3');}catch(InvalidArgumentException $e){$rejected=true;}remainingCheck($rejected,'Arbitrary multiplication not treated as tire size');
echo "Remaining catalog: rim rings, hole diameter, contextual diameter, explicit type evidence, compatible sizes and conflict guards OK\n";
